-- Role base: sin LOGIN/secret codificado. init-z-rls-user.sh configura LOGIN y password desde el entorno.\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_user') THEN\n        CREATE ROLE app_user WITH NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;\n    END IF;\nEND $$;\nGRANT CONNECT ON DATABASE construction TO app_user;\nGRANT USAGE ON SCHEMA public TO app_user;\nALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE\n    ON TABLES TO app_user;\nALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT\n    ON SEQUENCES TO app_user;